/**
 * Looks up the region whose inclusive postcode range contains the given postcode, or
 * {@code null} when the postcode is absent, not a 4-digit number, or in no known range.
 */
default String regionFromPostcode(String postcode) {
    if (postcode == null) {
        return null;
    }
    int value;
    try {
        value = Integer.parseInt(postcode.trim());
    } catch (NumberFormatException ex) {
        return null;
    }
    for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
        int[] range = entry.getValue();
        if (value >= range[0] && value <= range[1]) {
            return entry.getKey();
        }
    }
    return null;
}

